<script lang="ts">import {page}from '$app/state';import {onDestroy}from 'svelte';import {cancelPipelineRun,getPipelineDefinition,getPipelineRun,pipelineErrorMessage,retryPipelineRun,type NexetlError,type PipelineDefinition,type PipelineRun}from '$lib/api/pipelines';import {formatTimestamp}from '$lib/format';import PipelineWorkspaceNav from '$lib/components/PipelineWorkspaceNav.svelte';import PageHeader from '$lib/components/ui/PageHeader.svelte';import Button from '$lib/components/ui/Button.svelte';import Alert from '$lib/components/ui/Alert.svelte';import StatusBadge from '$lib/components/ui/StatusBadge.svelte';let pipeline=$state<PipelineDefinition|null>(null),run=$state<PipelineRun|null>(null),error=$state(''),timer:ReturnType<typeof setTimeout>|null=null,pending=$state(false);$effect(()=>{const{id,runId}= {id:page.params.pipelineDefinitionId,runId:page.params.runId};if(id&&runId)void load(id,runId)});onDestroy(()=>{if(timer)clearTimeout(timer)});async function load(id:string,runId:string){try{[pipeline,run]=await Promise.all([pipeline??getPipelineDefinition(id),getPipelineRun(id,runId)]);if(!['SUCCEEDED','FAILED','CANCELLED'].includes(run.status))timer=setTimeout(()=>load(id,runId),2000)}catch(e){error=pipelineErrorMessage(e as NexetlError)}}async function cancel(){if(!run)return;pending=true;try{run=await cancelPipelineRun(run.pipelineId,run.id)}catch(e){error=pipelineErrorMessage(e as NexetlError)}finally{pending=false}}async function retry(){if(!run)return;pending=true;try{const next=await retryPipelineRun(run.pipelineId,run.id);location.href=`/pipelines/${run.pipelineId}/runs/${next.id}`}catch(e){error=pipelineErrorMessage(e as NexetlError)}finally{pending=false}}</script>
<svelte:head><title>Run Details | NEXETL</title></svelte:head>{#if pipeline}<PageHeader title={pipeline.name} description={`Run ${run?.id??''}`}>{#if run&&!['SUCCEEDED','FAILED','CANCELLED'].includes(run.status)}<Button variant="secondary" loading={pending} onclick={cancel}>Cancel</Button>{:else if run&&['FAILED','CANCELLED'].includes(run.status)}<Button loading={pending} onclick={retry}>Retry run</Button>{/if}</PageHeader><PipelineWorkspaceNav pipelineId={pipeline.id}/>{/if}{#if error}<Alert variant="error">{error}</Alert>{/if}{#if run}<section class="summary"><div><span>Status</span><StatusBadge state={run.status}/></div><div><span>Version</span><strong>v{run.version}</strong></div><div><span>Trigger</span><strong>{run.triggerType}</strong></div><div><span>Queued</span><strong>{formatTimestamp(run.queuedAt)}</strong></div><div><span>Duration</span><strong>{run.durationMs===null?'Running':`${run.durationMs} ms`}</strong></div><div><span>Rows written</span><strong>{run.metrics.rowsWritten??0}</strong></div></section>{#if run.errorMessage}<Alert variant="error">{run.errorCode}: {run.errorMessage}</Alert>{/if}<div class="grid"><section><h2>Node execution</h2><div class="nodes">{#each run.nodes??[] as node}<article><div><strong>{node.label}</strong><small>{node.kind.replaceAll('_',' ')}</small></div><StatusBadge state={node.status}/><dl><div><dt>Input</dt><dd>{node.inputRows}</dd></div><div><dt>Output</dt><dd>{node.outputRows}</dd></div><div><dt>Rejected</dt><dd>{node.rejectedRows}</dd></div><div><dt>Duration</dt><dd>{node.durationMs??'—'} ms</dd></div></dl>{#if node.errorMessage}<p>{node.errorCode}: {node.errorMessage}</p>{/if}</article>{/each}</div></section><section><h2>Event log</h2><div class="events">{#each run.events??[] as event}<div><time>{formatTimestamp(event.timestamp)}</time><strong>{event.event.replaceAll('_',' ')}</strong><span>{event.message}</span></div>{/each}</div></section></div>{/if}
<style>.summary{display:grid;grid-template-columns:repeat(6,1fr);margin-bottom:1.2rem;border:1px solid var(--border-default);border-radius:var(--radius-lg);background:#fff}.summary>div{padding:.8rem;border-right:1px solid var(--border-subtle)}.summary>div:last-child{border:0}.summary span,.summary strong{display:block}.summary span{margin-bottom:.25rem;color:var(--text-muted);font-size:.58rem;text-transform:uppercase}.summary strong{font-size:.72rem}.grid{display:grid;grid-template-columns:1.35fr 1fr;gap:1rem}.grid>section{min-width:0}h2{font-size:.85rem}.nodes,.events{display:grid;gap:.5rem}.nodes article,.events div{border:1px solid var(--border-default);border-radius:var(--radius-md);background:#fff;padding:.7rem}.nodes article{display:grid;grid-template-columns:1fr auto;gap:.6rem}.nodes small{display:block;color:var(--text-muted);font-size:.58rem;text-transform:capitalize}.nodes dl{display:grid;grid-column:1/-1;grid-template-columns:repeat(4,1fr);margin:0}.nodes dl div{border-top:1px solid var(--border-subtle);padding-top:.45rem}.nodes dt{color:var(--text-muted);font-size:.58rem}.nodes dd{margin:0;font-size:.7rem}.nodes p{grid-column:1/-1;margin:0;color:var(--danger);font-size:.65rem}.events div{display:grid;grid-template-columns:auto 1fr;gap:.2rem .6rem;font-size:.65rem}.events time{color:var(--text-muted)}.events strong{text-transform:capitalize}.events span{grid-column:2;color:var(--text-secondary)}@media(max-width:900px){.summary{grid-template-columns:repeat(3,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:550px){.summary{grid-template-columns:repeat(2,1fr)}}</style>
